<script setup lang="ts">import{computed,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import type{DirectoryItem}from'../../domain/types';type ViewState='READY'|'EMPTY'|'UNAVAILABLE'|'ERROR';const item=ref<DirectoryItem|null>(uni.getStorageSync('directoryItem')||null),readError=ref(false);const state=computed<ViewState>(()=>readError.value?'ERROR':!item.value?'EMPTY':item.value.publicationState==='ELIGIBLE'?'READY':'UNAVAILABLE')</script>
<template><view class="page"><AppHeader left="← 信息" right="报错" @left="uni.navigateBack()"/><view class="content"><text class="kicker">信息详情 / UX-P041</text><view class="heading" role="heading" aria-level="1">{{state==='READY'?item?.title:'信息条目'}}</view><view v-if="state==='EMPTY'" class="card" role="status"><text class="card-title">暂无内容</text><text class="copy">当前没有可展示的内容引用，可返回列表。</text></view><view v-else-if="state==='UNAVAILABLE'" class="card" role="status"><text class="card-title">内容不可用</text><text class="copy">证据缺失、过期、投诉待查或 UNKNOWN 时发布资格为 0。</text></view><view v-else-if="state==='ERROR'" class="card" role="alert"><text class="card-title">内容读取失败</text><text class="copy">读取错误不等于内容不存在或已下架。</text></view><template v-else><text class="verified">✓ 指定范围已核验</text><view class="card"><view class="kv"><text>核验范围</text><text>{{item?.verificationScope}}</text></view><view class="kv"><text>来源类别</text><text>{{item?.sourceType}}</text></view><view class="kv"><text>核验日期</text><text>{{item?.verifiedAt}}</text></view><view class="kv"><text>更新时间</text><text>{{item?.updatedAt}}</text></view></view><view class="notice">已核验不代表官方认证、平台推荐、持续有效或平台担保。</view></template></view><view class="action"><button class="primary" @click="uni.showToast({title:'Mock报错未外发',icon:'none'})">报告信息错误</button><button class="secondary" @click="uni.navigateBack()">返回列表</button></view></view></template><style src="../../styles/shared.css"></style><style scoped>.verified{display:inline-block;color:var(--success);background:#e4f4ec;border-radius:999rpx;padding:8rpx 12rpx}.notice{margin-top:24rpx;padding:24rpx;border-radius:22rpx;background:#fff8f1}</style>
